// One output item per contact, with the full WhatsApp API payload ready to send.
const b = $input.first().json.body || {};
const contacts = Array.isArray(b.contacts) ? b.contacts : [];
if (!b.campaignId || !b.templateName || !b.language) {
  throw new Error('campaignId, templateName and language are required');
}
return contacts.map(c => {
  const params = Array.isArray(c.params) ? c.params : [];
  const template = { name: b.templateName, language: { code: b.language } };
  if (params.length) {
    template.components = [{
      type: 'body',
      parameters: params.map(p => ({ type: 'text', text: String(p) }))
    }];
  }
  return { json: {
    campaignId: b.campaignId,
    phone: String(c.phone),
    payload: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: String(c.phone),
      type: 'template',
      biz_opaque_callback_data: b.campaignId,   // comes back in every status webhook
      template
    }
  }};
});

// Turn the WhatsApp API response (success OR error body) into one row for the Messages sheet.
const src = $('Prepare Messages').item.json;
const r = $json || {};
const id = r.messages && r.messages[0] && r.messages[0].id;
const e = r.error || null;
let err = '';
if (!id) {
  if (e && typeof e === 'object') {
    const details = (e.error_data && e.error_data.details) || e.message || '';
    err = `${e.code || ''} ${details}`.trim();
  } else {
    err = e ? String(e) : 'unknown error (no message id returned)';
  }
}
return { json: {
  campaign_id: src.campaignId,
  phone: src.phone,
  wa_message_id: id || '',
  send_status: id ? 'accepted' : 'failed',
  error: err,
  sent_at: new Date().toISOString()
}};
